import { useState, useEffect } from 'react';
import type { CSSProperties } from 'react';
import { Document, Page, pdfjs } from 'react-pdf';
import type { BmpRecord } from '../data/bmpMaster.ts';
// Generated by scripts/extract_checklist_fields.mjs; rerun it if the PDF changes
import checklistFields from '../data/checklistFields.json';

import "react-pdf/dist/Page/AnnotationLayer.css";
import "react-pdf/dist/Page/TextLayer.css"
// Legacy build polyfills newer JS (e.g. Uint8Array.toHex) missing in some browsers
import workerUrl from "pdfjs-dist/legacy/build/pdf.worker.min.mjs?url";

type OverlayField = {
  id: string;
  page: number;                     // 0-based
  type: 'text' | 'textarea' | 'checkbox' | 'radio';
  label: string;                    // nearby PDF text, e.g. "Project/BMP Name"
  group?: string;                   // radio group, e.g. "p1-BMP Type:"
  left: number; top: number;        // scale-1 px from the page's top-left
  width: number; height: number;
};

pdfjs.GlobalWorkerOptions.workerSrc = workerUrl;

const FIELDS = checklistFields as OverlayField[];

const isoDate = (v?: string) => (v && /^\d{4}-\d{2}-\d{2}$/.test(v) ? v : '');
const todayIso = () => {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}
// Header text fields prefilled from the master list, by label (every checklist has the same header)
const PREFILL: Record<string, (r: BmpRecord) => string | undefined> = {
  'Project/BMP Name': r => r.name,
  'Plan/BMP # if applicable': r => r.sfNumber,
  'Date BMP Placed into Service': r => isoDate(r.mdeClosure),
  'Date of Inspection': () => todayIso(),
};

// Text fields hold strings, checkboxes booleans, radio groups the id of the chosen option
type Values = Record<string, string | boolean>;

type Props = { file: string; data: BmpRecord | null; scale?: number };

export default function PdfViewer({ file, data, scale = 1.25 }: Props) {
  const [numPages, setNumPages] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [values, setValues ] = useState<Values>({});
  useEffect(() => {
    if (!data) return;
    const initial: Values = {};
    for (const f of FIELDS) {
      const fill = f.type === 'text' ? PREFILL[f.label]?.(data) : undefined;
      if (fill) initial[f.id] = String(fill);
    }
    setValues(initial);
  }, [data]);

  const set = (key: string, value: string | boolean) => setValues(v => ({ ...v, [key]: value }));

  const renderField = (f: OverlayField) => {
    const box: CSSProperties = {
      position: 'absolute',
      left: f.left * scale,
      top: f.top * scale,
      width: f.width * scale,
      height: f.height * scale,
      margin: 0,
      boxSizing: 'border-box',
      zIndex: 3,                    // above the canvas
    };
    const textStyle: CSSProperties = {
      ...box,
      fontSize: Math.min(10, f.height * 0.75) * scale,
      padding: `0 ${2 * scale}px`,
      border: 'none',
      background: 'rgba(0, 112, 175, 0.12)',
    };
    switch (f.type) {
      case 'checkbox':
        return <input key={f.id} type="checkbox" title={f.label} style={box}
          checked={values[f.id] === true} onChange={e => set(f.id, e.target.checked)} />;
      case 'radio':
        return <input key={f.id} type="radio" title={f.label} style={box} name={f.group}
          checked={values[f.group!] === f.id} onChange={() => set(f.group!, f.id)} />;
      case 'textarea':
        return <textarea key={f.id} title={f.label} style={{ ...textStyle, resize: 'none', lineHeight: 1.2 }}
          value={String(values[f.id] ?? '')} onChange={e => set(f.id, e.target.value)} />;
      default:
        return <input key={f.id} title={f.label} style={textStyle}
          value={String(values[f.id] ?? '')} onChange={e => set(f.id, e.target.value)} />;
    }
  };

  return (
    <div 
      style={{
        width: "80%",
      }}
    >
      {error && <p>{error}</p>}
      <Document
        file={file}
        onLoadSuccess={({numPages}) => {
          setNumPages(numPages);
          setError(null);
        }}
        onLoadError={(err) => {
          setError(err.message);
        }}
        loading={<p>Loading PDF...</p>}
      >
        {Array.from({ length: numPages }, (_, i) => (
          <Page
            key={i}
            pageNumber={i + 1}
            scale={scale}
            renderTextLayer={false}        // otherwise these layers can steal clicks
            renderAnnotationLayer={false}
          >
            {FIELDS.filter(f => f.page === i).map(renderField)}
          </Page>
        ))}
      </Document>
    </div>
  )
}
